package org.eclipse.rdf4j.workbench.proxy;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;

import java.net.URL;
import java.net.URLClassLoader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

import org.eclipse.rdf4j.workbench.support.TestFilterConfig;
import org.eclipse.rdf4j.workbench.support.TestServletConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.mock.web.MockServletContext;

import jakarta.servlet.http.HttpServletResponse;

/**
 * An invalid {@code workbench.properties} is reported when the Workbench starts, but the application stays up in every
 * servlet container: the Workbench gateway loads without failing, and the Workbench pages and its root answer
 * {@code 503 Service Unavailable} with the configuration error until the file is fixed and the Workbench restarted.
 */
@ResourceLock("thread-context-class-loader")
class InvalidWorkbenchPolicyTest {

	private static final String INVALID_KEY = "menu.item.query.colour";

	@TempDir
	Path tempDir;

	@Test
	void theWorkbenchStartsAndAnswersItsPagesWithThePolicyError() throws Exception {
		withInvalidPolicy(() -> {
			MockServletContext context = new MockServletContext();
			WorkbenchGateway gateway = new WorkbenchGateway();
			Map<String, String> params = new LinkedHashMap<>();
			params.put("default-server", "http://127.0.0.1:9/rdf4j-server");
			params.put("change-server-path", "/NONE/server");
			params.put("default-path", "/NONE/repositories");
			params.put("cookie-max-age", "60");

			assertThatCode(() -> gateway.init(new TestServletConfig("workbench", context, params)))
					.as("an invalid policy does not stop the Workbench, and with it the application, from starting")
					.doesNotThrowAnyException();

			for (String pathInfo : new String[] { "/NONE/repositories", "/NONE/server", "/memory/query" }) {
				MockHttpServletRequest request = new MockHttpServletRequest("GET",
						"/rdf4j-workbench/repositories" + pathInfo);
				request.setContextPath("/rdf4j-workbench");
				request.setServletPath("/repositories");
				request.setPathInfo(pathInfo);
				MockHttpServletResponse response = new MockHttpServletResponse();

				gateway.service(request, response);

				assertPolicyError(response);
			}
			gateway.destroy();
		});
	}

	@Test
	void theWorkbenchRootAnswersThePolicyErrorToo() throws Exception {
		withInvalidPolicy(() -> {
			RedirectFilter filter = new RedirectFilter();
			filter.init(new TestFilterConfig("redirect", new MockServletContext(), Map.of("/", "/repositories")));
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/rdf4j-workbench/");
			request.setContextPath("/rdf4j-workbench");
			request.setServletPath("/");
			MockHttpServletResponse response = new MockHttpServletResponse();
			AtomicBoolean passedOn = new AtomicBoolean();

			filter.doFilter(request, response, (req, resp) -> passedOn.set(true));

			assertThat(passedOn).isFalse();
			assertPolicyError(response);
		});
	}

	private static void assertPolicyError(MockHttpServletResponse response) throws Exception {
		assertThat(response.getStatus()).isEqualTo(HttpServletResponse.SC_SERVICE_UNAVAILABLE);
		assertThat(response.getContentType()).startsWith("text/plain");
		assertThat(response.getContentAsString())
				.contains("workbench.properties")
				.contains(INVALID_KEY)
				.contains("restart");
	}

	private interface PolicyTest {
		void run() throws Exception;
	}

	/** Runs the test with an invalid classpath override of the Workbench policy. */
	private void withInvalidPolicy(PolicyTest test) throws Exception {
		Path classpathRoot = tempDir.resolve("classpath");
		Path classpathFile = classpathRoot.resolve("org/eclipse/rdf4j/common/app/config/workbench.properties");
		Files.createDirectories(classpathFile.getParent());
		Files.writeString(classpathFile, INVALID_KEY + "=red\n", StandardCharsets.UTF_8);
		Thread thread = Thread.currentThread();
		ClassLoader originalClassLoader = thread.getContextClassLoader();
		try (URLClassLoader testClassLoader = new URLClassLoader(new URL[] { classpathRoot.toUri().toURL() },
				originalClassLoader) {
			@Override
			public URL getResource(String name) {
				return super.getResource(name.startsWith("/") ? name.substring(1) : name);
			}
		}) {
			thread.setContextClassLoader(testClassLoader);
			test.run();
		} finally {
			thread.setContextClassLoader(originalClassLoader);
		}
	}
}
